import{_ as t,a as i,b as r,c as o}from"./chunks/9d5a068df60e30009bbe.DQKq5Wg3.js";import{_ as s,C as l,o as n,c as h,j as e,a as m,E as c,a6 as d}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"打造成功一人企业，我希望早点知道的11个深刻见解","description":"","frontmatter":{"title":"打造成功一人企业，我希望早点知道的11个深刻见解","originalTitle":"11 Insights I Wish I Knew To Make My One-Person Business A Success","date":"2022-10-22","originalUrl":"https://thedankoe.com/letters/11-insights-i-wish-i-knew-to-grow-my-one-person-business/","minutes":14,"sourceHash":"eb68f08d849e0dfff4c2a6b9616ce3ec74084f5991d0bc1c19a58dee20ed9da4","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/11-insights-i-wish-i-knew-to-grow-my-one-person-business/"}]]},"headers":[],"relativePath":"letters/11-insights-i-wish-i-knew-to-grow-my-one-person-business.md","filePath":"letters/11-insights-i-wish-i-knew-to-grow-my-one-person-business.md"}'),_={name:"letters/11-insights-i-wish-i-knew-to-grow-my-one-person-business.md"};function g(f,p,u,b,k,w){const a=l("ArticleMeta");return n(),h("div",null,[p[0]||(p[0]=e("h1",{id:"打造成功一人企业-我希望早点知道的11个深刻见解",tabindex:"-1"},[m("打造成功一人企业，我希望早点知道的11个深刻见解 "),e("a",{class:"header-anchor",href:"#打造成功一人企业-我希望早点知道的11个深刻见解","aria-label":'Permalink to "打造成功一人企业，我希望早点知道的11个深刻见解"'},"​")],-1)),c(a),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/JgTG1aoaB5s?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>当我最初踏上这段商业旅程时，是出于好奇。</p><p>我善于观察。</p><p>我观察了那些我不想成为的人，也观察了那些我想成为的人。</p><p>这二者之间的对比在我很小的时候（大概15岁时）就变得非常清晰。</p><p>硬币的一面，人们：</p><ul><li>身材走样</li><li>生活不快乐</li><li>不愿改变</li></ul><p>一种被每周薪水拴住的生活方式。</p><p>硬币的另一面，人们：</p><ul><li>过着梦想中的生活</li><li>传播着伟大的信息</li><li>激励他人变得更好</li></ul><p>他们中的大多数都是社交媒体早期的创作者。</p><p>有些人会抛出那句经典的论调：“但他们内心深处可能都不快乐！”</p><p>*然后瞬间关死任何潜在的机会，回到他们自己不快乐的生活方式中*</p><p>你可能是对的，但如果你了解我，你会知道我喜欢不带偏见地去质疑（在我的自尊允许的范围内）。</p><p>意思是，为什么我不能在生活的方方面面都富有？</p><p>我必须亲自体验那种光鲜亮丽的生活方式，并与那些人交谈，才能做出评判，不是吗？</p><p>如果他们其实很快乐，只是被大众误解了呢？</p><p>如果他们不快乐，为什么他们不改变呢？</p><p>这促使我尝试了他们推荐的任何东西、所有东西。</p><p>我尝试了健身房，然后爱上了它。</p><p>我尝试了新技能，然后爱上了学习。</p><p>我失败过很多次，也曾偏离正轨，但最终达到了这样一个节点：我的知识、技能和经验已经复利积累到了我标准下的“成功”。</p><p>凭借对未来持续采取微小行动的愿景，我成功建立了一家一人企业，它让我能够：</p><ul><li>研究我热爱的事物</li><li>用创造性的方式写下它们</li><li>完全控制自己的工作量</li><li>完全控制自己的居住地</li><li>打造本可以帮助我的产品和服务（以便它们能帮助你）</li></ul><p>这种生活方式唯一的缺点恰恰就是，你拥有完全的控制权。如果你没有驾驭这种自由的技能，你的大脑可能无法应对这种无序。</p><p>在这封信中，我想分享一些独特且可操作的经验，帮助你也实现同样的目标。</p><p>任何人都可以做到这一点，我希望有朝一日能看到一大批人，将他们作为人类所能提供的价值打包，把自己的天赋赠予世界。这就是有意识的创业。</p><p>在我们深入探讨这些经验之前，Digital Economics（数字经济学）课程将在4天后开课。如果你想用你现有的知识和技能建立一家一人企业，<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">可以考虑在这里报名。</a></p><h2 id="_1-一切都是流量与报价-offers" tabindex="-1">1) 一切都是流量与报价（Offers） <a class="header-anchor" href="#_1-一切都是流量与报价-offers" aria-label="Permalink to &quot;1) 一切都是流量与报价（Offers）&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>商业就是一场创造优秀产品或服务，并将其展现在对的人面前的游戏。</p><p>是的，营销、推广策略和其他方面确实有很多细节……但人们往往过度沉迷于此。如果你在周六晚上去一家热闹的酒吧（流量），尽可能多地去搭讪（报价/提案），你很可能会全垒打。太多人从一开始就追求完美，结果变成了非自愿的（财务上的）禁欲者。</p><p>很多人不明白的是，这就是一场游戏而已。</p><p>它并不是任何人的专属特权。</p><p>如果你足够聪明，你可以做你以前买过的一款产品的分销（affiliate），写一篇推特长文推广它，花钱让人转发，单靠这个就能赚取全职收入。既然产品很好，你赚到的钱就<em>应该</em>超过你花在付费推广上的钱。这就是广告的全部意义。投资回报率（ROI）。</p><p>这是一种适合新手的方法，但能帮你顺便积累受众。这样一来，当你经验足够丰富时，你就可以为自己的产品或服务如法炮制。而且，随着时间推移，你就不必再为流量花钱，因为你已经通过优质内容建立了自己的流量池。</p><p>当然，你可以在建设个人品牌的过程中暂缓变现，但大多数人这样做仅仅是因为别人告诉他们要这么做。</p><h2 id="_2-你需要3个杠杆" tabindex="-1">2) 你需要3个杠杆 <a class="header-anchor" href="#_2-你需要3个杠杆" aria-label="Permalink to &quot;2) 你需要3个杠杆&quot;">​</a></h2><p>一旦你建立了杠杆（通过持续拉动正确的<em>杠杆</em>），你就会获得别人无法想象的自由。</p><p>让我们假设你有一些东西可以卖。如果你没有，这件事应该全天候24小时占据你的大脑。你必须在长时间散步时思考它，沉浸在与你类似的人正在销售的东西中，并准备好在灵感闪现时全身心地投入构建。</p><p>一项自由职业、咨询、辅导或训练营服务。</p><p>或者一门课程、实体工具、会员、付费新闻信，亦或是如上所述的分销产品。</p><p>如果你不知道怎么做，去学。</p><p>现在，你需要在3件事情之间取得平衡。</p><p>增长、培育和变现。</p><p>这些就是杠杆。这意味着你需要学习、发现并执行对这些领域至关重要的行动。这些行动几乎是日常性的，一旦你找到了对你的业务有效的方法，就应该将它们系统化。</p><p><strong>杠杆1) 增长</strong></p><p>如果你的粉丝或品牌没有在持续增长，那就是有问题。解决它。</p><p>大多数人没有增长，是因为他们自视甚高，瞧不上那些能带来增长的内容风格。</p><p>内容，以及为该内容获取流量，就是你实现增长的方式。</p><p>市场上90%的人都是新手。</p><p>这意味着你在漏斗顶端社交媒体上的内容，应该主要都是与你选择的兴趣或专业知识相关的基础建议。</p><p>你的社交媒体品牌应该足够宽泛，以吸引这些新手，这样你才能将他们培育并引导向更进阶的内容。</p><p>附注：你确实可以在社交媒体上做超级细分领域，我只是个人不喜欢那样。你把自己关在一个盒子里，减少了自己转身的空间，而且无法谈论各种相互交叉的兴趣（举个例子，生产力、自我提升和商业就能极其完美地重叠）。</p><p><strong>杠杆2) 培育</strong></p><p>如果你是一个价值创作者（而不是一个娱乐博主、梗图账号或评论账号），那么你的<em>全部工作</em>就是教育你的受众。</p><p>如果你的社交媒体正在吸引一张大网中的海量人群，你需要教育并培育他们，直到他们购买你的产品。这就是你改变他人生活、建立权威，并证明你不仅仅是个花瓶的方式。</p><p>新闻信、引流诱饵（lead magnet）或其他长内容对于价值创作者来说是必不可少的。这就是你展示知识肌肉并传授你兴趣的地方（与你销售的产品相关）。</p><p>跳过这一教育步骤的品牌，在变现其受众时总是会困难重重。</p><p><strong>杠杆3) 变现</strong></p><p>别骗自己了，你在这里就是为了赚钱的。如果你才刚刚起步，这就是你考虑做这件事的全部原因。你对自己越诚实，你在销售时就越能表现得真实。这没什么错，你需要钱。不要因为你想把那个控制你生活的东西拿回到自己的掌控之中，就任由别人让你感到内疚。</p><p>最终，你会在你的工作中发现更深层的意义和目标，但无论如何，你必须维持生存。</p><p>你需要测试不同的促销活动、角度以及你的推广方式。</p><p>你是打算每周用一条推特长文推广一次？还是只打算在新闻信中推广？亦或打算每天在相关帖子下面推广一次？</p><p>一旦你知道什么能带来销售，你就可以开始将其系统化并使之成为你日常工作的一部分，这样收入就会变得更具可持续性。</p><p>在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>中，我们帮你系统化你的品牌、内容和产品，遵循这3个社交杠杆支柱。这就是大多数一人企业所缺失的，他们也正因此沦为了普通商品。</p><h2 id="_3-质疑一切" tabindex="-1">3) 质疑一切 <a class="header-anchor" href="#_3-质疑一切" aria-label="Permalink to &quot;3) 质疑一切&quot;">​</a></h2><p>不幸的是，“质疑一切”已经变得过于主流，以至于它作为一条建议已经失去了原本的冲击力。</p><p>质疑是我在商业上取得成功的驱动力。</p><p><em>“你必须垂直深耕细分领域！”</em></p><p>谁说的？</p><p><em>“粉丝不到1万你就不能卖东西！”</em></p><p>谁说的？</p><p><em>“你不可能每天工作2小时，一年还能赚100万美金！”</em></p><p>我虽然还没做到这一点，但这到底是谁说的？！</p><p>去他妈的自我设限，证明它们是错的（为了你自己，也为了你的粉丝）。</p><p>这就是乐趣所在。这场游戏提出了一个挑战，它会一脚把你踢进心流状态。</p><p>固执一点。</p><p>当人们说你做不成你想做的事情时，<strong>做第一个找到出路的人。</strong></p><p>这就是你获取能够为你建立名声和财富的知识的方式。</p><h2 id="_4-解构一切" tabindex="-1"><strong>4) 解构一切</strong> <a class="header-anchor" href="#_4-解构一切" aria-label="Permalink to &quot;**4) 解构一切**&quot;">​</a></h2><p>意识和创造力是信息时代成功的驱动力。它们决定了你如何在更深层次上思考、生活和产生影响力。</p><p>在硬币的反面，无意识和思想封闭是通向平庸的必由之路。</p><p>创造力就是把意识的点滴连接起来。</p><p><img src="'+i+'" alt=""></p><p>你通过直接意识到生活中的那个瞬间来体验事物。</p><p>通过不对你看到的任何冰山一角封闭心智，你会变得更有意识。</p><p>每一件事物（Every-thing）都是冰山一角。</p><p>每一件事物都是由各个部分组成的整体。</p><p>一切都是一个事物。一个思考的单位。意识的虚构。一个部分和一个整体。</p><p>这些部分也构成了其他的整体，这意味着它们是相连的。</p><p>生活不过如此。宇宙是一个将自身分裂成无限部分的整体。而每一个部分本身又是一个整体。人类是整体。他们是自我发现的探测器。当我们发现自我时，宇宙也就发现了自身。无事可做，却又万事可做。乐在其中吧。</p><p>你通过质疑潜入冰山之下。</p><p><strong>整体</strong>：一本关于生产力的书</p><p><strong>部分</strong>：生产力的原则，提高生产力的策略，抓住你注意力并帮助你理解所学内容的故事和轶事。</p><p>通过把这些记下来，你能用其中一个有趣的故事或轶事来阐述另一个观点吗？</p><p>在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>中，我谈到了电子舞曲（EDM）如何与成为一名创作者有着异曲同工之妙。</p><p>每位EDM制作人都有自己独特的声音，他们将不同的声音融合在一起，带领人们经历一系列的高潮和低谷。</p><p>创作者有他们独特的基调，他们将各种想法融合在一起，带领人们经历他们生活的高潮和低谷。</p><p>我也可以用EDM的现场演出（live sets）来说明生活的高潮和低谷。如果DJ只是一刻不停地播放硬核音乐，那会很无聊。如果你的生活全都是高潮而没有低谷，它也会变得无聊。</p><p>练习解构你看到的下一件事（真的是任何事）。提出问题。</p><h2 id="_5-不要放弃-要转向-pivot" tabindex="-1"><strong>5) 不要放弃，要转向（Pivot）</strong> <a class="header-anchor" href="#_5-不要放弃-要转向-pivot" aria-label="Permalink to &quot;**5) 不要放弃，要转向（Pivot）**&quot;">​</a></h2><p>每个人都在担心“闪亮物体综合症”。</p><p>你需要明白的是，你完全被允许带着复利积累的知识“重新开始”。</p><p>你完全被允许在一个更好的位置上重新开始，带着可迁移的技能，以及那些激发你“重新开始”的新技能。</p><p>如果你学习了网页设计，并且看到一个机会去运用那项技能然后全身心投入文案写作，你为什么不这么做呢？</p><p>那不是闪亮物体综合症，那是技能叠加。从长远来看，它会为你赚更多的钱。</p><p>如果你仍在朝着同一个宏大而宽泛的目标（比如财务自由）努力，在这个过程中你就必须不断调整方向。</p><p>如果你放弃了那个大目标，你就是在放弃你的未来。这可不好。</p><p>当然，你可以因为看到了一个机会而放弃某项技能。你最初的技能不会消失，尤其是在你下一次创业时可能还会用到它的时候。</p><p>知识会复利，技能会复利，总体而言，好习惯都会产生复利。</p><p>这就是为什么我是个人品牌和一人企业的铁粉。你的兴趣会变。你的技能、知识、经验、认知和人脉会产生复利。你是一个人。人类会进化。如果你走这条路，你的企业会和你一起进化。事实上，它就是加速进化的容器。</p><p>别放弃，去转型。</p><h2 id="_6-靠-抄袭-走向成功" tabindex="-1">6) 靠“抄袭”走向成功 <a class="header-anchor" href="#_6-靠-抄袭-走向成功" aria-label="Permalink to &quot;6) 靠“抄袭”走向成功&quot;">​</a></h2><p>成功是一场聪明的模仿游戏。</p><p><img src="'+r+'" alt=""></p><p>别装得好像你从出生起就没有模仿过周围的一切，只为了觉得自己“有原创性”、聪明或是风趣。</p><p>你可能确实如此，但自我的存在只能是相对于他人而言。你<em>以为</em>你是谁，不过是你一生中接触的环境、刺激和条件反射所构建的心理产物。</p><p>模仿是任何新手能遵循的最伟大的技能，就像你是一个刚刚降生在商业生活中的白板小孩。</p><ul><li>练习用你最喜欢的作者的口吻写作</li><li>用你最喜欢的账号发布的话题作为灵感</li><li>在竞争对手的落地页里，偷师他们所针对的痛点问题</li><li>拆解为什么某些帖子会疯传，以及它是否带来了收益</li><li>看看大家都在卖什么（意味着有市场），然后思考如何用你独特的经验创造出属于你自己的东西</li><li>阅读一个让你兴奋的想法，不要划重点，然后在不看原文的情况下把它写下来。通过从记忆中回想你学到的东西，让它变成你自己的</li></ul><p>在我继续进行更多哲学式的长篇大论之前，让我们言归正传。</p><h2 id="_7-最赚钱的细分领域就是你自己" tabindex="-1">7) 最赚钱的细分领域就是你自己 <a class="header-anchor" href="#_7-最赚钱的细分领域就是你自己" aria-label="Permalink to &quot;7) 最赚钱的细分领域就是你自己&quot;">​</a></h2><p><a href="https://open.spotify.com/embed/episode/6kmABq0SWE0FSGTJKip4LH?si=817415761e1c4121&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>传统的品牌、营销和销售建议正在走向终结。我们已经探索了现实的那个裂缝，并区分了其中的好与坏。</p><p>咄咄逼人的销售漏斗和机器般的写作有效，但效果已经大不如前。</p><p>如果你想抢占先机，那就<em>把自己产品化。</em></p><p>通过自我反思和迈尔斯-布里格斯（Myers Briggs，即MBTI）性格测试来了解你自己。</p><p>然后，把“你”当作你的目标客户画像。</p><p>追求你的目标，研究你的兴趣，并在网上写给你过去、现在和未来的自己。</p><p>没有人能复制真实。</p><p>世界上只有一个你，前提是你不是外部世界的奴隶。你说你是谁，你就是谁，而不是别人说你是谁。</p><h2 id="_8-自我觉察是关键" tabindex="-1">8) 自我觉察是关键 <a class="header-anchor" href="#_8-自我觉察是关键" aria-label="Permalink to &quot;8) 自我觉察是关键&quot;">​</a></h2><p>自我觉察（或者积极意义上的自我意识）会帮助你比任何人都更快地学习大多数技能。</p><p>如果你是一个创作者、拥有个人品牌或其他形式的单干创业者，你就会明白持续输出高质量内容的必要性。</p><p>这意味着你必须精通人类行为学和心理学。</p><p>在这种情况下，你就是自己最好的老师。</p><p>为什么那篇长推文吸引了我的注意？</p><p>为什么我点赞并转发了它？</p><p>想想看，你希望别人也对你做同样的事。</p><p>所以，与其像我们平时那样盲目地划拉过去……</p><p>停下来，顿一下，然后去逆向工程。</p><p>赚钱也是一样。</p><blockquote><p>如果你想赚钱，先搞懂你为什么花钱。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1519636048430735365?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">April 28, 2022</a></p></blockquote><h2 id="_9-先开始-后学习" tabindex="-1">9) 先开始，后学习 <a class="header-anchor" href="#_9-先开始-后学习" aria-label="Permalink to &quot;9) 先开始，后学习&quot;">​</a></h2><p>信息无处不在。</p><p>在信息时代，人们犯下的一个巨大错误，就是让知识的获取超过了执行力。</p><p>是的，你什么都能学，但你真的学到什么了吗？</p><p>解决这个问题最好的办法就是规划一个项目。</p><ul><li>规划一份邮件通讯</li><li>规划一款产品</li><li>规划一项服务</li><li>规划你的人生</li></ul><p>然后，开始行动。</p><p>你的大脑会做好模式识别的准备。你的生活质量将一飞冲天，因为在你度过每一天时，你有了一个<em>项目</em>去<em>应用</em>你所学到、体验到和消费的一切。</p><p>创建一个项目，然后去寻找实现该项目所需的特定知识。别把自己困在“教程地狱”里。</p><h2 id="_10-创造你自己的职业生涯" tabindex="-1">10) 创造你自己的职业生涯 <a class="header-anchor" href="#_10-创造你自己的职业生涯" aria-label="Permalink to &quot;10) 创造你自己的职业生涯&quot;">​</a></h2><p>60% 的新工作甚至还没被创造出来。</p><p>也就是说，我们根本不知道它们会是什么样子。</p><p>我们唯一知道的是，它们在互联网上。</p><p>价值创作者们正在无时无刻地创造着新工作。</p><p>互联网允许人们去追求新目标，这意味着人生中有了可以走的新路径，这也意味着有更多的问题需要解决。</p><p>教育行业根本跟不上，所以价值创作者们在铺路，并把他们的心得体会浓缩成内容、课程和其他形式的教育媒体。</p><p>我见过音乐制作导师、草药治疗专家、自信心教练，甚至还有生物黑客教练（专注于提升头脑、身体和精神表现的药*物……比如致幻剂）。</p><p>你如何创造属于自己的职业生涯？</p><p>通过追求你自己广泛的兴趣，把它们变成一个独立的类别，并用它们来解决问题。</p><p>如果你对心态、生产力和商业感兴趣……那都可以归入“生活方式设计”、“个人主权”或其他什么名字的“细分领域”。然后，你去<em>创造</em>这个新类别背后的意义、理论和哲学。</p><p>我的类别是一人企业。我把你作为神圣“创作者”的概念与灵性结合起来，并通过我的亲身经历形成了自己看待它的方式。</p><h2 id="_11-缺乏经验不是借口" tabindex="-1">11) 缺乏经验不是借口 <a class="header-anchor" href="#_11-缺乏经验不是借口" aria-label="Permalink to &quot;11) 缺乏经验不是借口&quot;">​</a></h2><p>自我（ego）为了让你相信你干不成某件事而展现出的那套心理体操，简直令人难以置信。</p><p>如果我让你开始在网上写作，并告诉你这能给生活和事业带来20多个好处，你的大脑会怎么反驳？</p><p>“我不擅长写作。”</p><p>“只有网红才能积攒受众。”</p><p>“在建立受众之前，我只是在做自由职业。”</p><p>虽然这些借口都很蠢，而且错多于对，但最后一个实在是有些太扯了。</p><p>你的意思是，你不想免费输出信息（因为你缺乏经验），但你却打算去为别人的企业做免费或付费的<em>工作</em>，而那可是牵涉到真金白银的营收的？你怎么给自己圆这个逻辑？</p><p>写作能让你厘清思绪。写作能让你明确你所知的东西。写作能为你打开一种可能性——提出一个（非抄袭的）<em>真正</em>的解决方案，进而能卖出更多的钱。</p><p>学习技能，运用技能（用在你身上，因为个人品牌需要一个企业所需的一切技能），教你所学的东西，然后把它卖出去。</p><p>做和所有人相反的事。</p><p><img src="'+o+'" alt=""></p><p>每个人都恰恰漏掉了全貌中那些能促使他们采取行动的拼图。</p><p>别让恐惧支配你，让你永远停留在原地。</p><p><em><strong>– Dan Koe</strong></em></p><p>P.S. 数字经济学（Digital Economics）课程4天后开营。</p><p>如果你想要一个完整的Notion仪表盘，用于启动、发展和规模化你的一人企业，<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">考虑报名吧。</a></p><p>我们将携手合作，打造一个独特的品牌、真实的声音、未被开发的细分领域，以及（从你旅程一开始就）能真正卖得出去的产品或服务。</p><hr><p><a href="/en/letters/11-insights-i-wish-i-knew-to-grow-my-one-person-business">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',184))])}const E=s(_,[["render",g]]);export{x as __pageData,E as default};
